import{_ as s,H as n,f as a,i as r}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"11-WebIDE：如何让函数远离繁琐的本地开发模式？","description":"","frontmatter":{},"headers":[{"level":2,"title":"WebIDE 的优势是什么？","slug":"webide-的优势是什么","link":"#webide-的优势是什么","children":[]},{"level":2,"title":"整体架构","slug":"整体架构","link":"#整体架构","children":[{"level":3,"title":"VS Code Server","slug":"vs-code-server","link":"#vs-code-server","children":[]},{"level":3,"title":"Serverless Extension","slug":"serverless-extension","link":"#serverless-extension","children":[]},{"level":3,"title":"环境依赖","slug":"环境依赖","link":"#环境依赖","children":[]},{"level":3,"title":"弹性伸缩","slug":"弹性伸缩","link":"#弹性伸缩","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"延伸阅读","slug":"延伸阅读","link":"#延伸阅读","children":[]}],"relativePath":"Serverless进阶实战课/11-WebIDE：如何让函数远离繁琐的本地开发模式？.md","filePath":"Serverless进阶实战课/11-WebIDE：如何让函数远离繁琐的本地开发模式？.md","lastUpdated":1795535054000}'),t={name:"Serverless进阶实战课/11-WebIDE：如何让函数远离繁琐的本地开发模式？.md"};function i(p,e,l,o,E,d){return n(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="_11-webide-如何让函数远离繁琐的本地开发模式" tabindex="-1">11-WebIDE：如何让函数远离繁琐的本地开发模式？ <a class="header-anchor" href="#_11-webide-如何让函数远离繁琐的本地开发模式" aria-label="Permalink to &quot;11-WebIDE：如何让函数远离繁琐的本地开发模式？&quot;">​</a></h1><p>你好，我是静远。</p><p>在开始今天的主题之前，我想跟你先聊一下我的客户在 WebIDE 这块的诉求。我在金融领域客户的提问中挑选了两个比较典型的问题：</p><ul><li><p>银行要求生产环境不带自己的电脑，请问我如何操作我们的代码？</p></li><li><p>编辑框有点小，我用的是 Python，是否能提供在线调试的能力？</p></li></ul><p>你会发现，不管是工作硬性的要求还是自身对开发效率的追求，他们最终的目的，都是希望有一个能够随时随地、打开即用的代码编辑器——WebIDE。</p><p>我想，WebIDE 这个概念你一定不陌生，但如何让 WebIDE 更好地用于函数计算的开发呢？我们又需要注意哪些细节呢？这里面有哪些不一样的技术点呢？</p><p>今天，我就来跟你聊一聊函数计算中 WebIDE 是如何工作的。希望通过这节课程，让你在了解 VS Code Server 原理的基础上，在插件机制、环境的依赖、弹性伸缩等几个方面都对函数计算形态的 WebIDE 有一个比较清晰的认识。</p><h2 id="webide-的优势是什么" tabindex="-1">WebIDE 的优势是什么？ <a class="header-anchor" href="#webide-的优势是什么" aria-label="Permalink to &quot;WebIDE 的优势是什么？&quot;">​</a></h2><p>首先，我们来体验一下云厂商的 WebIDE，直观感受一下它的优势。</p><p>我们可以以阿里云函数计算 FC 为例，创建一个 Python3 语言运行时的函数。点击控制台页面的“函数代码”，就可以加载出来在线编辑的工作空间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/1.png" alt=""></a></p><ul><li>初始化完成后的WebIDE界面</li></ul><p>我们可以看到，这和我们本地的 VS Code IDE 几乎没有太大差别，左上角是我们熟悉的“文件”、“资源管理器”、“查找”等菜单按钮。而且，在线编写代码的体验和本地 IDE 也几乎是一样的，包括代码提示功能等都有。当你完成代码编写之后，还可以点击测试按钮，直接测试编写的函数。确认无误后，点击部署函数，测试好的代码也可以直接部署在云端。</p><p>这种方式的好处是，当我们想要细微调整函数的时候，无需下载代码到本地，可以直接在线完成编辑、测试、部署这一系列的动作。</p><p>现在，我想你应该对 WebIDE 的优势有一个直观的感受了：可快速地编辑、调试、运行、部署云端代码。它的另一个优势就是在金融银行领域，出于安全的考虑，有的环境往往是不能带自己的电脑和本地 IDE 的，只能通过 WebIDE 的方式来操作。</p><p>针对函数计算的 WebIDE，各大云厂商都有不同程度的实现，虽然不管是在公有云还是在私有云上，实现方面可能有一定的差异，但背后的实现思想和机制是通用的。接下来，就让我们深入了解它的整体架构。</p><h2 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h2><p>为了让你更直观地理解在线的函数计算 IDE，我在架构图中用不同的颜色做了标识。我分别来做一下说明。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/2.png" alt=""></a></p><ol><li><p>蓝色部分：是 WebIDE 客户端的核心，我们选取了知名的VS Code Server来作为核心底座，它在很大程度上解决了 Client 端的问题，其自身基于 VS Code 二次开发，让 VS Code在任何地方都可以通过浏览器访问和操作；</p></li><li><p>绿色部分：是将 WebIDE 与函数计算结合起来的核心，主要包括函数计算业务形态下的功能插件、工具、SDK 以及运行时环境能力；</p></li><li><p>橘色部分：是 Serverless 形态下的必备支撑服务，承担代码的存储、安全管控和针对用户操作请求时的资源调度和伸缩事项，主要包括对象存储、权限认证、资源伸缩、健康监测能力。</p></li></ol><p>在图中，我也用序号标注了 WebIDE 在函数计算平台的简要执行过程，接下来，我以一个函数的 Deploy 请求为例，帮助你从整体上快速了解每次请求涉及的全貌。</p><p>第 1-2 步，用户会在 VS Code 的前端页面向后端发出函数在线编辑的请求，假设为“XXX/deployFunction”，那么服务端，也就是函数计算的控制层 Controller 在接收到请求后，就会验证权限，再转给 VS Code Server 容器实例。</p><p>第 3-4 步，VS Code Server 容器就会获取用户代码，再加载函数计算的资源调度系统，也会根据目前容器池 Container Pool 的资源现状，动态扩缩容 WebIDE Pod 资源。</p><p>第 5-7 步，Server 端根据用户的请求，会调用插件后端功能 Serverless Extension BE，基于此时语言的环境，执行 Deploy 操作，并将执行结果返回给 Client 端。</p><p>这里需要额外说明三点：</p><p>第一，我们可以将 Serverless Extension 插件提前集成在 VS Code Server 的镜像里面；</p><p>第二，Runtime 依据原来函数计算执行的架构来部署即可，你可以将各语言运行时打包成一个镜像，然后以动态挂载的方式加载每个语言，也可以集成在 WebIDE 的大镜像里面，不过这样会比较笨重；</p><p>第三，健康监测主要用于监听 VS Code Server 的状态。虽然网页版的服务都在服务端运行，但界面 Client 和后台 Server 是有心跳关联的，这个健康监测的作用，就是心跳监测。它会按照一定的逻辑来判断页面是否不再使用，以便通知资源调度服务，释放后端的容器实例。</p><p>基于基础架构和流程的展示，我们应该已经能够理解，函数计算的 WebIDE 的主要功能就在于，基于一个可视化的在线编辑软件的基础，增加了 Serverless 函数计算的插件功能，通过集成运行时环境依赖和弹性伸缩的能力，提供用户在线开发、调试、部署和运行函数的能力。</p><p>接下来，我们就沿着这个思路，对可视化的在线编辑软件 VS Code Server、ServerlessExtension 插件功能、环境依赖和弹性伸缩的能力，依次展开说明，看看它们有什么需要注意的技术要点。</p><h3 id="vs-code-server" tabindex="-1">VS Code Server <a class="header-anchor" href="#vs-code-server" aria-label="Permalink to &quot;VS Code Server&quot;">​</a></h3><p>我在开头提到过，本次讨论基于 VS Code Server 来展开，主要是因为 VS Code 的背景公司是微软，使用人群基数庞大。微软将 VS Code 进行了开源，而 Code Server 又对 VS Code进行了二次封装，使其可以在任何机器上部署并且通过浏览器来访问。</p><p>我们还是来体验一下，这样更直观一点。</p><p>首先，你需要提前准备一个 2 核 4G 的机器（区别于 code-server 在 github 上的最低要求 2核 1G），确保执行所需的空间资源，并且确保有 docker 环境。</p><p>接下来，你可以下载 code-server 镜像到本地，并启动为容器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 拉取vscode server镜像到本地</span></span>
<span class="line"><span>$ docker pull jmcdice/vscode-server</span></span>
<span class="line"><span># 启动一个docker</span></span>
<span class="line"><span># -d是在后台运行容器</span></span>
<span class="line"><span># -p将本地的端口（9000）映射到容器的端口（8080）</span></span>
<span class="line"><span># --restart=always是在重启容器时，能重新启动参数</span></span>
<span class="line"><span># --name指定启动容器的名字</span></span>
<span class="line"><span>$ docker run -d -p 9000:8080 --restart=always --name=myVscodeServer jmcdice/vscod</span></span></code></pre></div><p>启动动完成之后，我们要使用 docker ps 命令，查看容器是否已经启动。最后，我们在浏览器中输入 127.0.0.1:9000，就可以使用在线 VS Code 了，这个流程操作下来是非常方便、快捷的。</p><p>需要注意的是，我们这里只是以本地 docker 的方式启动了 VS Code，如果我们想对外使用，只需要申请部署云服务器，并对外暴露 URL 就可以了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/3.png" alt=""></a></p><p>有了本地的体验，我们放到函数计算平台，无非就是新增一个镜像并启动为容器的过程。我们的重点，是集成函数服务的能力，这就是我们下面要讨论的 Serverless Extension 插件功能了。</p><h3 id="serverless-extension" tabindex="-1">Serverless Extension <a class="header-anchor" href="#serverless-extension" aria-label="Permalink to &quot;Serverless Extension&quot;">​</a></h3><p>各大云厂商基于 WebIDE，通过开发插件 Extension 的方式集成了函数平台的常用功能。</p><p>如百度智能云函数计算的 Baidu Serverless VS Code 插件、腾讯云函数的 Tencent ServerlessToolkit for VS Code 插件、阿里云函数计算的 Aliyun Serverless VSCode Extension 插件等等。从产品形态上来看，大体比较类似，你选择其中一个来体验就行。</p><p>但要注意的是，各云厂商的 VS Code 插件底层实现都是集成了自家的命令行工具和 SDK 的，如百度智能云集成了BSAM CLI、腾讯云集成了Serverless Framework 语法、阿里云的插件结合了函数计算命令行工具 Funcraft和函数计算 SDK的功能。</p><p>那么，他们都是怎么实现的呢？虽然各家集成的工具和 SDK 多多少少带有自家的特性，但设计的通用原则是不变的。接下来，我就以这种通用的设计法则和思路，来阐述如何构建一个Serverless VS Code Extension。</p><p>首先，我们可以发现，各家的插件都是放在了微软 Visual Studio Marketplace 之上，你可以从这里任意点击一个插件进去，可以看到相应的源代码、手册等维护信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/4.png" alt=""></a></p><p>其次，该插件只是一个端的体现，还是得由函数计算平台的 SDK 和 CLI 命令工具来实现。例如函数的上传、下载功能底层，都是调用 SDK 中函数的接口实现，而函数的部署、依赖安装、调试、执行，则一般是在 CLI 中实现的。</p><p>总结起来就是两部分，一部分是端的 UI 层逻辑的体现，集成在 VS Code 里面，一部分是工具CLI 和 SDK 的集成，用于真正执行相关的命令，在服务端容器中运行。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/5.png" alt=""></a></p><p>我们可以将 CLI、SDK、Serverless Extension 与 VS Code Server 打包在一个大镜像里面，在请求的时候，通过下载镜像，在启动后为容器提供服务。</p><h3 id="环境依赖" tabindex="-1">环境依赖 <a class="header-anchor" href="#环境依赖" aria-label="Permalink to &quot;环境依赖&quot;">​</a></h3><p>接下来，我们需要了解比较关键的一步——如何让函数“跑”起来。这就涉及到环境依赖了。</p><p>根据编程语言的不同特性，通常函数计算平台需要针对各个语言做不同的 Runtime，为了区别于正式生产环境下的 Runtime，我这边采用 dev-runtime 命名。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Serverless%E8%BF%9B%E9%98%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/11-WebIDE/6.png" alt=""></a></p><p>它们主要的不同就在于，dev-runtime 需要根据不同的指令，来进行不同的操作，比如根据 UI层发送的部署指令，进行 deploy 操作。而我们之前第一模块中提到的 Runtime，是运行态直接挂载的。通常，函数计算平台也是会对 Runtime 和 dev-runtime 进行区分，分开管理的。</p><p>这里，我们具体看下 dev-runtime 的执行流程。我以 Python3 的调试为例，简单跟你聊一下这个过程。</p><p>就 Python3 而言，如果需要支持调试，我们需要提前在 Docker 镜像中指定安装 debugpy。有的操作系统可能还需要安装 GCC。</p><p>我们通常可以通过一个脚本来接收各种指令，并调起各个依赖工具。那么，针对 Python3 语言，如果接收到 WebIDE 安装扩展依赖的指令，就可以通过 pip3 来 install 了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># -r 安装需求文件里的依赖包</span></span>
<span class="line"><span># -t 安装目标位置</span></span>
<span class="line"><span># -i 指定镜像源，本案例指定清华源，具体你可以自定义</span></span>
<span class="line"><span># -I 如果已经安装依赖，忽略</span></span>
<span class="line"><span>/XXX/bin/pip3 install -I -r /XXX/requirements.txt -t /XXX/site-packages -i https:</span></span></code></pre></div><p>类似的，如果需要支持调试和执行，通过 Python3 和 debugpy 相应的命令来执行即可。而其他语言的调试实现，依赖于各语言的调试方式，比如 Node.js 会使用 node-inspect 调试工具。</p><p>需要补充说明的是，虽然我在文章开头指出大部分云厂商在其公有云上不支持 Java 的在线WebIDE 的能力。但其实，Java 也是可以支持网页版能力的，我们只需要在 Java 调试的启动脚本中，添加相应的命令启动调试即可。</p><h3 id="弹性伸缩" tabindex="-1">弹性伸缩 <a class="header-anchor" href="#弹性伸缩" aria-label="Permalink to &quot;弹性伸缩&quot;">​</a></h3><p>到这里，针对函数计算的 WebIDE 已经讲解得差不多了。但如果只是这样，它还不能被称为“Serverless”的，我们需要再给它加上一层“可弹”的特性。</p><p>这其实和我们前面涉及到的扩缩容有些类似，我先给你一个思路，之后你也可以自己完整走一遍 Serverless 下的 WebIDE 流程。</p><p>关于这一层“可弹”的特性，你可以通过 KEDA、Prometheus、HPA、metrics 来支撑 WebIDE在 Kubernetes 环境下的动态扩缩容。为什么需要引入 KEDA？如果结合扩缩容 那一节课，你应该可以很快回答出来，因为 KEDA 可以支持 0-1 之间的切换。</p><p>最后，还剩一个比较重要的问题，就是我在基础架构图中画的“健康监测”。为什么要有这个功能呢？</p><p>我们可以这么想，前端页面和提供服务的 VS Code Server 在第一次建立链接后，是需要有页面的触发，才会有下一步的执行动作的。那么，如果用户没有触发，该怎么办？是释放掉容器实例还是持续存在？存在多久合适呢？</p><p>比较合理的设计是在 VS Code Server 中存在两个进程，Server 进程负责和前端页面的 Edit请求交互，而 Status 管理进程负责状态管理上报。其中，VS Code Server 和前端通信的协议一般使用 WebSocket 协议。</p><p>依据这样的设计思路，当 WebIDE 前端和 Server 超过一定时间没有响应时，可能就是网络原因了。此时不会立马回收 VS Code Server 容器实例，会重试连接一定次数。当连接成功时，就会继续使用该容器实例。如果重试仍然连接失败，就说明该容器实例已经不再被使用了，会将该实例标记为不可用状态，定期执行清除任务，将不可用状态的容器实例回收。</p><p>通过这样的状态监测管理，使得我们函数计算平台的 WebIDE 也是“可弹”的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>最后，我来小结一下我们今天的内容。这节课，我从函数计算 WebIDE 的整体架构出发，分别介绍了它的核心四要点：VS Code Server、Serverless Extension、环境依赖、弹性伸缩。</p><p>在课程的开头，我们通过云厂商已经发布的 WebIDE 体验了一次，清晰直观地感受到了我们今天内容的价值：使用 Web IDE，不仅能对用户的代码进行快速的编辑和修改，还能够高效地加载代码所需的外部依赖，从而大大降低开发人员重新部署的次数以及时间。</p><p>再来，通过整体架构的介绍，相信你已经从概貌上了解了设计一个 Serverless 形态的WebIDE 需要考虑的四大要点。我们一个一个来说。</p><p>首先，VS Code Server 的讲解，主要想向你传递两件事情：第一，code-server 是对 VSCode 的二次封装，让我们平时在本机使用的 VS Code 可以无处不在的访问；第二，函数计算平台也是站在巨人的肩膀上，进一步构建属于 Serverless 下的 WebIDE 的。这对于我们平时在设计架构和工作中也有一定的启发：没必要什么事情都自己重复去造轮子。</p><p>其次，Serverless Extension 和环境依赖是本节课的“灵魂”，没有了这两个功能，就不能称之为函数计算形态下的 WebIDE。它们主要是基于函数计算的工具 CLI 和 SDK，以及调试需要下不同运行时的封装。</p><p>最后，为了符合 Serverless 的“可弹”特性，我也从扩缩容的角度，介绍了 VS Code Server在容器中的两种服务的进程，希望你能清晰地了解网页版“端和服务”的联动关系。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>好了，这节课到这里也就结束了，最后我给你留了一个思考题。</p><p>如果让你来在现有云厂商平台上新增支持 Java 的在线调试功能，你打算如何实现？</p><p>欢迎在留言区写下你的思考和答案，我们一起交流讨论。感谢你阅读，也欢迎你把这节课分享给更多的朋友一起交流学习。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>你可以通过VS Code 插件官网搜索到对应的插件库，更详细地了解 extension 是如何实现的。</p>`,84)])])}const c=s(t,[["render",i]]);export{b as __pageData,c as default};
